import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, join, resolve, sep } from "node:path";

/**
 * Where original files live. Local disk for now; the interface lets us swap in S3/R2 later
 * without touching the code that uploads or ingests files.
 */
export interface FileStorage {
  put(key: string, data: Uint8Array): Promise<void>;
  get(key: string): Promise<Uint8Array>;
  delete(key: string): Promise<void>;
}

export function createLocalFileStorage(rootDir: string): FileStorage {
  const root = resolve(rootDir);

  /** Keys are generated by us, but never let one escape the storage folder ("../../etc"). */
  function pathFor(key: string): string {
    const full = resolve(join(root, key));
    if (!full.startsWith(root + sep)) throw new Error(`Invalid storage key: ${key}`);
    return full;
  }

  return {
    async put(key, data) {
      const path = pathFor(key);
      await mkdir(dirname(path), { recursive: true });
      await writeFile(path, data);
    },
    async get(key) {
      return new Uint8Array(await readFile(pathFor(key)));
    },
    async delete(key) {
      await rm(pathFor(key), { force: true });
    },
  };
}
